preimage[0] = 0x01;
preimage[1..33].copy_from_slice(&left);
preimage[33..65].copy_from_slice(&right);
assert_eq!(parent, sha256_digest(&preimage));

items.docMarkdown:
Builds a complete DIG Network D5/D8 Merkle tree in contiguous arenas and returns its 32-byte root.

Reduces `leaves` level by level using two ping-pong `Vec<[u8; 32]>` buffers (`current` and `next`
swapped via `core::mem::swap` to avoid per-level reallocations). Paired siblings `(current[i], current[i + 1])`
are hashed with [`dig_hash_pair`] (D5 `0x01` prefix), while any trailing odd node at the end of a
level is promoted unchanged to the next level (D8 odd-leaf carry-up). If `leaves` is empty,
returns `SHA-256(b"")`.

# Arguments

* `leaves` - Slice of 32-byte leaf digests in canonical tree order.

# Returns

The 32-byte DIG Network D5/D8 Merkle root digest.

# Complexity

`O(N)` time (`N - 1` calls to [`dig_hash_pair`] for `N >= 1`) and `O(N)` contiguous heap arena
space (`1.5 * N` 32-byte slots across the two ping-pong buffers).

# Examples

```rust
use dbrain_core_rs::merkle::{build_dig_merkle_tree_arena, dig_hash_pair, sha256_digest};

// Empty tree commits to SHA-256(""):
assert_eq!(build_dig_merkle_tree_arena(&[]), sha256_digest(&[]));

// Three leaves demonstrate D5 pair hashing + D8 odd-leaf carry-up of `l2`:
let l0 = [0x01u8; 32];
let l1 = [0x02u8; 32];
let l2 = [0x03u8; 32];
let root = build_dig_merkle_tree_arena(&[l0, l1, l2]);
assert_eq!(root, dig_hash_pair(&dig_hash_pair(&l0, &l1), &l2));
```

items.example:
use dbrain_core_rs::merkle::{build_dig_merkle_tree_arena, dig_hash_pair, sha256_digest};

// Empty tree commits to SHA-256(""):
assert_eq!(build_dig_merkle_tree_arena(&[]), sha256_digest(&[]));

// Three leaves demonstrate D5 pair hashing + D8 odd-leaf carry-up of `l2`:
let l0 = [0x01u8; 32];
let l1 = [0x02u8; 32];
let l2 = [0x03u8; 32];
let root = build_dig_merkle_tree_arena(&[l0, l1, l2]);
assert_eq!(root, dig_hash_pair(&dig_hash_pair(&l0, &l1), &l2));

use dbrain_core_rs::merkle::{build_dig_merkle_tree_arena, verify_dig_merkle_proof_bytes};

let l0 = [0xAAu8; 32];
let l1 = [0xBBu8; 32];
let root = build_dig_merkle_tree_arena(&[l0, l1]);

// Serialize a 1-step inclusion proof for `l1` with left sibling `l0` (`is_left = 1`):
let mut proof = Vec::with_capacity(101);
proof.extend_from_slice(&l1);                  // leaf32
proof.extend_from_slice(&1u32.to_be_bytes());  // path_count = 1
proof.extend_from_slice(&l0);                  // sibling32
proof.push(1u8);                               // sibling is on the left
proof.extend_from_slice(&root);                // expected_root32

let (computed, expected, valid) = verify_dig_merkle_proof_bytes(&proof).unwrap();
assert!(valid);
assert_eq!(computed, expected);

